import React from "react";

const ToDoItem = ({id, text="Nuevo To Do", onChecked}) => {
  return (
    <div
      onClick={ () => {
        onChecked(id);
      }}
    >
      <li>{text}</li>
    </div>
  );
}

export default ToDoItem;
